#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Interval {
    pub min: i32,
    pub max: i32,
}

impl Interval {
    pub fn new(min: i32, max: i32) -> Self {
        // Enforce the "valid interval" requirement.
        assert!(min < max, "invalid interval: min must be < max");
        Self { min, max }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ChebyshevPoly {
    pub coeffs: Vec<i32>, // coefficients in increasing degree order
    pub domain: Interval, // default [-1, 1]
    pub window: Interval, // default [-1, 1]
}

/// Constructs a Chebyshev polynomial descriptor from non-empty i8 coefficients.
///
/// Requirements satisfied:
/// - Coefficients converted to i32, preserving length and order
/// - Default domain interval [-1, 1]
/// - Default window interval [-1, 1]
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Input is assumed non-empty by the problem statement; keep an assertion
    // to guard invariants in debug/testing contexts.
    assert!(!coef.is_empty(), "coef must be non-empty");

    let coeffs: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    let domain = Interval::new(-1, 1);
    let window = Interval::new(-1, 1);

    ChebyshevPoly {
        coeffs,
        domain,
        window,
    }
}

